import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"觀","description":"焦氏易林注 - 觀","frontmatter":{"title":"觀","description":"焦氏易林注 - 觀"},"headers":[],"relativePath":"classics/jiaoyilin/020.md","filePath":"classics/jiaoyilin/020.md"}'),l={name:"classics/jiaoyilin/020.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="觀" tabindex="-1">觀 <a class="header-anchor" href="#觀" aria-label="Permalink to “觀”">​</a></h1><h3 id="觀-1" tabindex="-1">觀 <a class="header-anchor" href="#觀-1" aria-label="Permalink to “觀”">​</a></h3><h3 id="觀之乾" tabindex="-1">觀之乾 <a class="header-anchor" href="#觀之乾" aria-label="Permalink to “觀之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>蜎飛蠕動，各有所配。歡悅相迎，鹹得其處。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《豫》。此用《觀》象。巽蟲，故曰蝟、曰蠕。</p><h3 id="觀之坤" tabindex="-1">觀之坤 <a class="header-anchor" href="#觀之坤" aria-label="Permalink to “觀之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>繼祀宗邑，追明成康。光照萬國，享世久長。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坤為邑、為萬國。《觀》艮為光明、為照、為久。</p><h3 id="觀之屯" tabindex="-1">觀之屯 <a class="header-anchor" href="#觀之屯" aria-label="Permalink to “觀之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>秋冬探巢，不得鵲雛。銜指北去，愧我少姬。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>伏兌為秋，坎為冬。艮為穴、為巢，艮手為探，兌為鵲雛，兌伏故不得。艮為指，坎為北，伏巽為少姬。坤為愧，巽少姬。本《大過》。</p><h3 id="觀之蒙" tabindex="-1">觀之蒙 <a class="header-anchor" href="#觀之蒙" aria-label="Permalink to “觀之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>僮妾獨宿，長女未室，利無所得。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為僮妾、為獨，坎為宿，艮為室，巽為長女、為利，巽伏故無得。</p><h3 id="觀之需" tabindex="-1">觀之需 <a class="header-anchor" href="#觀之需" aria-label="Permalink to “觀之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>洪波逆流，至人潛處。蓬蒿代柱，大屋顛僕。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>通《晉》。坎為水，坤水，故曰洪波。洪波，大波也。伏坤為逆，坎為聖，故曰至人。坎為潛，坤為薪，在艮屋下，故曰蓬蒿代柱。艮為屋柱，坤柔故顛僕。○洪，宋元本作鴻，從汲古。波，汲古作魚，依宋元本。至人，宋元本作主人，依汲古。處皆作去，依《同人》之《屯》校。</p><h3 id="觀之訟" tabindex="-1">觀之訟 <a class="header-anchor" href="#觀之訟" aria-label="Permalink to “觀之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>日暗不明，讒夫在堂。右臂疾痺，君失其光。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>離為日、為明，坎隱故暗。坎為夫，坎上下兌口相背，故曰讒夫。《觀》艮為堂、為臂，坎為疾。乾為君，離為光，坎隱故失光。○臂、痺，依汲古，宋元本訛闢、訛瘁。</p><h3 id="觀之師" tabindex="-1">觀之師 <a class="header-anchor" href="#觀之師" aria-label="Permalink to “觀之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>王孫季子，相與孝友。明允篤誠，升擢薦舉，為國乾輔。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>此用遇卦《觀》象。《觀》艮為孫、為季子，伏震為王，故曰王孫季子。坤順故曰孝友。艮為明允、為篤誠，伏震為薦舉、為乾，坤為國。○輔，依宋本，汲古作柱。</p><h3 id="觀之比" tabindex="-1">觀之比 <a class="header-anchor" href="#觀之比" aria-label="Permalink to “觀之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>麟趾龍身，日馭三千。南上蒼梧，與福為婚。道里夷易，安全無患。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>比亦用《觀》象。坤為麟、為身，伏乾為龍，為日、為千，艮納丙，數三，故曰三千。伏震為南、為蒼梧，乾為福，與坤配，故曰與福為婚。艮為道里，坎為平，故曰夷易。艮為安，坎為患，安故無患。○馭，依汲古，宋元本作取，非。</p><h3 id="觀之小畜" tabindex="-1">觀之小畜 <a class="header-anchor" href="#觀之小畜" aria-label="Permalink to “觀之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>三子成駒，破其堅車。輪載空輿，後時失期。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>伏震為子，數三，故曰三子。震為駒、為車，坎為破。伏艮為堅，故曰破其堅車。坎為輪，艮為時，震為後，故曰後時失期。全用伏象。○破其堅車，依宋元本，汲古作損折轅軸，不協。</p><h3 id="觀之履" tabindex="-1">觀之履 <a class="header-anchor" href="#觀之履" aria-label="Permalink to “觀之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>逐禍除患，道德神仙。遏惡萬裡，常歡以安。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>坎為禍患，坎伏故曰逐禍除患。伏艮為道，震為神，艮為仙，坤為萬裡、為惡，坤閉故曰遏惡。兌為歡。○禍，汲古作福，依宋元本。</p><h3 id="觀之泰" tabindex="-1">觀之泰 <a class="header-anchor" href="#觀之泰" aria-label="Permalink to “觀之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>黃池之盟，吳晉爭強。勾踐為患，夷國不安。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>兌為池，震黃，故曰黃池。震為南，故曰吳，為進，故曰晉。震為健，乾亦為健，故曰爭強。震為足，故曰踐。坤為夷、為國，坤喪故不安。○國，依宋元本，汲古作門，非。汲古多二句，為下《復》林詞，宋元本皆無。</p><h3 id="觀之否" tabindex="-1">觀之否 <a class="header-anchor" href="#觀之否" aria-label="Permalink to “觀之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>青牛白咽，招我於田。厯山之下，可以多耕。歲藏時節，人民安寧。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為牛，巽為白，伏兌為咽。坤為我、為田，艮為山、為時，故曰厯山，舜耕處也。坤為下，伏震為耕，坤為歲，艮為時，坤為民人、為安寧。○歲藏，依汲古，宋元本作歲露。人民，依宋元本，汲古作人保。歲藏時節者，言秋收冬藏之時也。</p><h3 id="觀之同人" tabindex="-1">觀之同人 <a class="header-anchor" href="#觀之同人" aria-label="Permalink to “觀之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>有頭無目，不見菽粟。消耗為疾，三年不復。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>乾為頭，離目，目應在頭上，今在下，故曰無目、故不見菽粟。巽為菽粟也。伏坤為消，坎為疾。坤為年，震數三，故曰三年。○不見菽粟，依宋本，汲古作赫赫粟粟，非。</p><h3 id="觀之大有" tabindex="-1">觀之大有 <a class="header-anchor" href="#觀之大有" aria-label="Permalink to “觀之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>山沒邱浮，陸為水魚。燕雀無巢，民無室廬。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。艮為山邱，在坎水坤水上，故曰山沒邱浮。坤為陸、為水、為魚，兌為燕雀，艮為巢、為室廬，坤為民，坎陷故曰無巢、無室廬也。</p><h3 id="觀之謙" tabindex="-1">觀之謙 <a class="header-anchor" href="#觀之謙" aria-label="Permalink to “觀之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>高岡鳳凰，朝陽梧桐。雍雍喈喈，菶菶萋萋。陳辭不多，以告孔嘉。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詩《捲阿》篇：&quot;鳳凰鳴矣，於彼高岡；梧桐生矣，於彼朝陽。菶菶萋萋，雝雝喈喈&quot;。又曰&quot;矢詩不多，維以遂歌&quot;。林全用詩語。艮為高岡，坤文為鳳，震為朝，伏離為日。震為鳴，故曰雍喈，為茂盛，故曰萋菶。震為言，故曰辭、曰告，為孔，故曰孔嘉。○雍雍，與《毛詩》異文，宋元本作噰。</p><h3 id="觀之豫" tabindex="-1">觀之豫 <a class="header-anchor" href="#觀之豫" aria-label="Permalink to “觀之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>鰥寡獨宿，憂動胸臆，莫與宿食。艮為鰥，坎為宿，坤為寡，故曰鰥寡獨宿。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>坎為憂，坤為腹、為胸臆，震口為食。○宿食，汲古作笑食，依宋元本。</p><h3 id="觀之隨" tabindex="-1">觀之隨 <a class="header-anchor" href="#觀之隨" aria-label="Permalink to “觀之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>馬蹄躓車，婦惡破家。青蠅汙白，恭子離居。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為馬、為蹄，蹄，音弟，與踶同，蹋也，馬踶故車躓。震為車，二至四震覆，故曰躓車。巽為婦，坤為惡，艮為家，兌毀，故曰破家。巽為蠅，震為青，故曰青蠅。巽為白，震為子，巽順，故曰恭子，謂申生也。艮為居。○馬蹄躓車，依《革》之《解》校，各本皆作&quot;躓馬破車&quot;，與下句不對。青蠅，《小雅》篇名，傷讒而作。</p><h3 id="觀之蠱" tabindex="-1">觀之蠱 <a class="header-anchor" href="#觀之蠱" aria-label="Permalink to “觀之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>長女三嫁，進退無羞。逐狐作妖，行者離憂。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽為長女，震為嫁，數三，故曰三嫁。巽為進退，艮為狐，震為逐、為行，互坎為憂、為妖。</p><h3 id="觀之臨" tabindex="-1">觀之臨 <a class="header-anchor" href="#觀之臨" aria-label="Permalink to “觀之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>人無足，法緩除。牛出雄，走羊驚。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>陽不制陰，男失其家。震為人，伏巽下斷，故無足。除，授官也。坤柔故緩，言人有疾不能授官也。坤為牛，震為雄，坤在上，故曰出雄。兌為羊，震為走、為驚，故曰走羊驚，陽少陰多故曰不制。震為男，艮為家，艮伏故失。○前四為三字句，各本皆作&quot;人無定法，緩除才出，地雄走歸&quot;，汲古除才出又作行長姦，大都皆作四字句，茲依《既濟》之《屯》校。</p><h3 id="觀之觀" tabindex="-1">觀之觀 <a class="header-anchor" href="#觀之觀" aria-label="Permalink to “觀之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>厯山之下，虞舜所處。躬耕至孝，名聞四海。為堯所薦，纘位天子。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為時，故曰厯山。坤為下，伏震為帝，故曰虞舜、曰堯。艮為躬，巽順為孝。艮為名，坤為海，巽數四，故曰四海。伏震為子，艮為天，故曰天子。○虞舜、孝，依宋元本，汲古作虞唐、作教。纘位，依宋元本，汲古作禪。纘者，繼也。</p><h3 id="觀之噬嗑" tabindex="-1">觀之噬嗑 <a class="header-anchor" href="#觀之噬嗑" aria-label="Permalink to “觀之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>茹芝餌黃，飲食玉英。與神流通，長無憂兇。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>伏巽為芝，伏兌為茹、為餌，震為黃、為玉、為英，坎為飲食。震為神、為通，坎憂震樂，故無憂。芝，靈芝。黃，黃精，服之延年益壽。</p><h3 id="觀之賁" tabindex="-1">觀之賁 <a class="header-anchor" href="#觀之賁" aria-label="Permalink to “觀之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>東行無門，西出華山。道塞畏難，遊子為患。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>震為東、為行，艮為門，坎隱故無門。艮山，伏兌為西、為華，故曰華山。艮為道，坎為塞、為畏、為患，震為遊子。</p><h3 id="觀之剝" tabindex="-1">觀之剝 <a class="header-anchor" href="#觀之剝" aria-label="Permalink to “觀之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>壽如松喬，與日月俱。常安康樂，不罹禍憂。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《剝》。</p><h3 id="觀之復" tabindex="-1">觀之復 <a class="header-anchor" href="#觀之復" aria-label="Permalink to “觀之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>探鷇得螽，所願不喜。道值小人，君子咎蹇。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為鷇，伏巽為螽，坤憂故不喜。坤為小人，震為大塗、為道、為君、為子，坤為咎。○下二句依宋元本，汲古將前《泰》林羼入此處，非。</p><h3 id="觀之無妄" tabindex="-1">觀之無妄 <a class="header-anchor" href="#觀之無妄" aria-label="Permalink to “觀之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>蠃生子，深目黑醜。雖飾相就，眾人莫取。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《恆》。蠃即蜾字。蠃音騾，《說卦》離為蠃是也。</p><h3 id="觀之大畜" tabindex="-1">觀之大畜 <a class="header-anchor" href="#觀之大畜" aria-label="Permalink to “觀之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>喜怒不時，霜雪為災。稼穡無功，后稷饑寒。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為喜、為威，故為怒。艮為時，三至上正覆震艮，故曰不時。乾為冰、為霜雪，兌毀故災。震為稼穡、為稷，乾為後、為寒。○饑寒，依汲古，元本作飢憂。</p><h3 id="觀之頤" tabindex="-1">觀之頤 <a class="header-anchor" href="#觀之頤" aria-label="Permalink to “觀之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>烏升鵲舉，照臨東海。尨降庭堅，為陶叔後。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>封圻蓼六，履祿綏厚。詳《需》之《大畜》。</p><h3 id="觀之大過" tabindex="-1">觀之大過 <a class="header-anchor" href="#觀之大過" aria-label="Permalink to “觀之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>黃離白日，照我四國。元首昭明，民賴其福。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏《頤》為大離，《離六二》曰&quot;黃離元吉&quot;，故離為黃、為日、為照，下震為白，故曰白日。坤為國，震卦數四，故曰四國。乾為元首、為福，坤為民。</p><h3 id="觀之坎" tabindex="-1">觀之坎 <a class="header-anchor" href="#觀之坎" aria-label="Permalink to “觀之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>黍稷醕釀，敬奉山宗。神嗜飲食，甘雨嘉降。獨蒙福力，時災不至。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《需》。</p><h3 id="觀之離" tabindex="-1">觀之離 <a class="header-anchor" href="#觀之離" aria-label="Permalink to “觀之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>福過我裡，入門笑喜，與吾利市。通《坎》。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>震為福、為裡，艮為門，震為笑喜，巽為利市。○汲古首句多&quot;禍不更生&quot;四字，依宋元本。</p><h3 id="觀之鹹" tabindex="-1">觀之鹹 <a class="header-anchor" href="#觀之鹹" aria-label="Permalink to “觀之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>晝臥裡門，悚惕不安。目不得闔，鬼搔我足。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為裡門、為臥，乾為日、為晝、為悚惕，伏大離故目不得闔。闔，閉也。伏坤為鬼，震為足，艮手故曰搔足。○闔，宋元本作閡，依汲古。</p><h3 id="觀之恆" tabindex="-1">觀之恆 <a class="header-anchor" href="#觀之恆" aria-label="Permalink to “觀之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>春草榮華，長女宜夫。受福多年，世有封祿。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為春、為草、為榮華，巽為長女，震為夫、為福，乾為多、為年、為祿，伏坤為世。長女宜夫者，以震巽為配偶，故能受福也。</p><h3 id="觀之遯" tabindex="-1">觀之遯 <a class="header-anchor" href="#觀之遯" aria-label="Permalink to “觀之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>雍門內崩，賊賢傷仁。暴亂狂悖，簡公失位。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為門，伏兌悅故曰雍門。巽為隕、為崩，在內卦故曰內崩。乾為仁賢，陰消陽故曰賊賢傷仁。巽為賊也。遯弒君父，故曰亂悖。震為竹、為簡、為公，震伏故曰失位。《論語》：&quot;陳成子弒簡公&quot;，事在《左傳哀十四年》，陳成子既殺闞止，大陸子方亡出雍門&quot;，註：雍門，齊城門也。內崩，蓋言內亂。○仁，依汲古，宋元本作人。</p><h3 id="觀之大壯" tabindex="-1">觀之大壯 <a class="header-anchor" href="#觀之大壯" aria-label="Permalink to “觀之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>心志無良，昌披妄行。觸壁抵牆，不見戶房。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>伏坤為心志，坤惡故無良。震為昌、為行、為觸，伏艮為牆壁、為戶房，坤黑故不見。○心志、昌披，依宋元本，汲古作心壯、作猖獗。</p><h3 id="觀之晉" tabindex="-1">觀之晉 <a class="header-anchor" href="#觀之晉" aria-label="Permalink to “觀之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>膠車木馬，不利遠賈。出門為患，安止得全。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>互坎為膠，坤為車，故曰膠車。坤為馬，坎艮皆為木，故曰木馬。膠車不堅，木馬不動，故不利遠賈。艮為門，坎為患，艮為安止。○木馬，從宋元本，汲古作秣，與下句不接。得全，汲古作不危，依宋元本。</p><h3 id="觀之明夷" tabindex="-1">觀之明夷 <a class="header-anchor" href="#觀之明夷" aria-label="Permalink to “觀之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>家在海隅，橈短流深。企立望宋，無木以趨。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>坤為海，坎為室，故曰家在海隅。坎為橈、為流，坤坎皆為水，故曰流深。震為行，故曰企立。離為望。《說文》：&quot;以木架屋曰宋&quot;，故艮為宋，三至五互艮覆，故曰無木以趨。</p><h3 id="觀之家人" tabindex="-1">觀之家人 <a class="header-anchor" href="#觀之家人" aria-label="Permalink to “觀之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>冬葉枯槁，當風失道。蒙被塵埃，左右勞苦。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>坎為冬，巽為葉，離為枯槁，巽為風，坎為失，言葉埋道上而失道也。坎為勞。○冬葉，依宋本，汲古作冬桑。失，依汲古，宋元本作於。</p><h3 id="觀之睽" tabindex="-1">觀之睽 <a class="header-anchor" href="#觀之睽" aria-label="Permalink to “觀之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>過時不行，妄逐王公。老女無夫，不安其居。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>通《蹇》。艮為時、為反震，故不行、故妄逐。兌為老女，本《大過》也。艮為兌夫，艮伏故曰無夫。坎險故不安。○無夫，依汲古，宋元本作失度，非。</p><h3 id="觀之蹇" tabindex="-1">觀之蹇 <a class="header-anchor" href="#觀之蹇" aria-label="Permalink to “觀之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>履泥汙足，名困身辱。兩仇相當，自為痛疾。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>坎為泥、為汙，履足似用半震象。艮為名、為身，坎為困辱、為仇，重坎故曰兩仇、曰痛疾。○自為痛疾，依汲古，宋元本作身為疾病。</p><h3 id="觀之解" tabindex="-1">觀之解 <a class="header-anchor" href="#觀之解" aria-label="Permalink to “觀之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>精華墮落，形體醜惡。齟齬挫頓，枯槁腐蠧。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為精華，伏巽故墮落。離正反兌口相對，故曰齟齬。巽蟲故腐蠧。離火故枯槁。○形體，依元本，汲古作形容。</p><h3 id="觀之損" tabindex="-1">觀之損 <a class="header-anchor" href="#觀之損" aria-label="Permalink to “觀之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>長生無極，子孫千意。松柏為梁，堅固不傾。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《觀》。</p><h3 id="觀之益" tabindex="-1">觀之益 <a class="header-anchor" href="#觀之益" aria-label="Permalink to “觀之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>去辛就蓼，毒愈酷毒。避穽入坑，憂患日生。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>《說文》&quot;蓼，辛菜&quot;。巽納辛，震為蓼，坤為毒、為憂患，震為生，《詩》周頌雲：&quot;莫予茾蜂，自求辛螫。未堪家多難，予又集於蓼&quot;。 ○毒、穽、坑，依元本，汲古作甚、作井、作坎，又元本多&quot;不思我家&quot;一句。</p><h3 id="觀之夬" tabindex="-1">觀之夬 <a class="header-anchor" href="#觀之夬" aria-label="Permalink to “觀之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>行堯欽德，養賢致福。眾英積聚，國無寇賊。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>《夬》乾為帝王、為德，故曰行堯欽德。乾為賢為福，兌食故曰養賢致福。伏艮為君子，坤為眾、為聚、為國，故曰積眾。巽為寇賊，巽覆故無。</p><h3 id="觀之姤" tabindex="-1">觀之姤 <a class="header-anchor" href="#觀之姤" aria-label="Permalink to “觀之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>狗逐兔走，俱入谷口。與虎逢晤，迫不得去。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>象多未詳，疑用遇卦《觀》象。</p><h3 id="觀之萃" tabindex="-1">觀之萃 <a class="header-anchor" href="#觀之萃" aria-label="Permalink to “觀之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>望尚阿衡，太宰周公。藩屏湯武，立為侯王。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《訟》。</p><h3 id="觀之升" tabindex="-1">觀之升 <a class="header-anchor" href="#觀之升" aria-label="Permalink to “觀之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>清人高子，久屯外野。逍遙不歸，思我慈母。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《睽》。</p><h3 id="觀之困" tabindex="-1">觀之困 <a class="header-anchor" href="#觀之困" aria-label="Permalink to “觀之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>三蟲作蠱，削跡無與。勝母盜泉，居不安處。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>巽為蟲。《左傳》&quot;三蟲為蠱&quot;。伏震為跡，艮手艮刀，故曰削跡。巽為母，兌剛，故曰勝母。坎為水、為盜，故曰盜泉。艮為居、為安，艮伏兌折故不安。○蟲，依宋元本，汲古作蟲。《屍子》：&quot;孔子至勝母縣，暮矣而不宿，遇盜泉，渴矣而不飲&quot;。</p><h3 id="觀之井" tabindex="-1">觀之井 <a class="header-anchor" href="#觀之井" aria-label="Permalink to “觀之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>獹牝龍身，進無所前。三日五夜，得其所歡。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。震為龍，艮為狗。獹，良犬也。艮犬止震龍上，故曰獹牝龍身。艮為身，艮止故不進。離為日，震數三，故曰三日。坎為夜，納戊數五，故曰五夜。震為歡。○獹，宋元本作驢，今依汲古。牝，宋本、汲古作今，依元本。歡，宋元本作欽，依汲古。</p><h3 id="觀之革" tabindex="-1">觀之革 <a class="header-anchor" href="#觀之革" aria-label="Permalink to “觀之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>黃裹綠衣，君服不宜。淫湎毀常，失其寵光。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>《詩衛風》：&quot;綠兮衣兮，綠衣黃裹&quot;，《傳》謂衛莊公惑於嬖妾衣上僭也。《革》通《蒙》。震為衣、為黃、為君，《箋》謂綠衣當為素裹，今黃裹逾制，故曰不宜。坎為淫湎、為失，離為光。○《毛傳》謂姬妾衣服逾制，此則謂刺衛君，蓋以黃為正色，反以為裹而不宜也。與毛異。</p><h3 id="觀之鼎" tabindex="-1">觀之鼎 <a class="header-anchor" href="#觀之鼎" aria-label="Permalink to “觀之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>天所顧佑，禍災不到，安吉無懼。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>互乾為天，離為顧，坤為禍災，坤伏，故不到而安吉也。○到，宋元本作至，無作不，依汲古。</p><h3 id="觀之震" tabindex="-1">觀之震 <a class="header-anchor" href="#觀之震" aria-label="Permalink to “觀之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>盤紆九回，行道留難。止須於邱，乃睹所歡。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮止故盤紆。震數九為歸，故曰九回。震為行，艮為道，艮止故留難。艮為邱、為須，震為歡，艮為觀，故曰睹。○於，宋元本作子，今依汲古。</p><h3 id="觀之艮" tabindex="-1">觀之艮 <a class="header-anchor" href="#觀之艮" aria-label="Permalink to “觀之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>暴虐失國，為下所逐。北犇陰胡，主君旄頭。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為暴虐，坎為失，艮為國，故曰失國。坎為下，震為逐、為犇，坎為北、為陰胡。震為主君、為毛羽，坎為首，故曰旄頭。旄頭，被髪也。《漢官儀》&quot;選羽林為旄頭被髪先驅&quot;是也。樂彥《括地誌》&quot;夏桀死，其子葷粥北奔，逐水草而居，號曰匈奴&quot;。林詞全用其事。○胡，元本作月，依汲古。</p><h3 id="觀之漸" tabindex="-1">觀之漸 <a class="header-anchor" href="#觀之漸" aria-label="Permalink to “觀之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>御騂從龍，至霍華東。與禹相逢，送致於邦。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>騂，赤馬。坎為馬、為赤，故曰御騂。伏震為從、為龍，故曰御騂從龍。艮為山，坎西，故曰霍華。霍華，西方大山也。離為東，伏震為王，故曰禹。艮為邦。○霍、禹，依汲古，宋元本作於、作離。於，汲古作子，依宋元本。</p><h3 id="觀之歸妹" tabindex="-1">觀之歸妹 <a class="header-anchor" href="#觀之歸妹" aria-label="Permalink to “觀之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>銅人鐵距，雨露勞苦。終日卒歲，無有休息。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>伏艮為銅鐵，震為人、為距，故曰銅人鐵距。坎為雨露、為勞苦，互離為日，伏艮為終，震為歲，故終日卒歲。艮止為休息，艮伏故不息。○鐵，宋元本作，依汲古。</p><h3 id="觀之豐" tabindex="-1">觀之豐 <a class="header-anchor" href="#觀之豐" aria-label="Permalink to “觀之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>大人失宜，盈滿復虧。長成之木，盛者復衰。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震為大人，巽為虧，震為成長、為木、為盛，巽為隕落、為衰，蓋震巽相往來反覆。故林詞雲爾。○長成，宋元本作長冬，依汲古。木，元本作禾，依宋本、汲古。</p><h3 id="觀之旅" tabindex="-1">觀之旅 <a class="header-anchor" href="#觀之旅" aria-label="Permalink to “觀之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>梅李冬實，國多盜賊。亂擾並作，王不能制。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《師》。此以巽為盜賊。</p><h3 id="觀之巽" tabindex="-1">觀之巽 <a class="header-anchor" href="#觀之巽" aria-label="Permalink to “觀之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>澤枯無魚，山童無株。長女嫉妬，使身空虛。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>兌為澤，離枯，巽為魚枯，故無魚。伏艮為山，兌上缺為童。《莊子徐無鬼》&quot;堯聞舜賢，舉之童土之地&quot;，註：童，無草木也。巽為株、為長女，伏坎為嫉妬。艮為身，離為空虛。○無株，汲古作難株，從宋元本。</p><h3 id="觀之兌" tabindex="-1">觀之兌 <a class="header-anchor" href="#觀之兌" aria-label="Permalink to “觀之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>天門冬虛，既盡為災。膉黯蒼，秦伯受殃。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。艮居戌亥，故曰天門。坎為冬，陽窮在上故曰既盡。《廣韻》：&quot;膉，肥也，，醜也&quot;，膉黯蒼，言戌亥空亡渺冥無有也。兌為西，故曰秦。伏震為伯，坎為殃。○既盡，汲古作晉季，今依宋元本。黯蒼，依宋元本，汲古作默蒼。</p><h3 id="觀之渙" tabindex="-1">觀之渙 <a class="header-anchor" href="#觀之渙" aria-label="Permalink to “觀之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>牽衣涉河，水深漬罷。幸賴舟子，濟脫無他。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>罷，依《訟》之《萃》校，各本皆訛衣。罷，音婆。</p><h3 id="觀之節" tabindex="-1">觀之節 <a class="header-anchor" href="#觀之節" aria-label="Permalink to “觀之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>推車上山，高仰重難。終日至暮，不見阜巔。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為車，艮手為推、為山，故曰推車上山。艮為高仰，坎為暮，伏離為日，艮為重、為阜巔，坎隱伏故不見。○不見，宋本作不惟，元本作唯見，皆非，依汲古本。</p><h3 id="觀之中孚" tabindex="-1">觀之中孚 <a class="header-anchor" href="#觀之中孚" aria-label="Permalink to “觀之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>鼎煬其耳，熱不可舉。大路壅塞，旅人心苦。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>通《小過》。震為鼎，兌為耳，艮火在下，故煬其耳、故熱不可舉。震為大塗，互坎故壅塞。震為旅、為人，坎為心，《鼎九三》雲&quot;鼎耳革，其行塞&quot;，茲依《睽》之《比》，皆作&quot;大塗壅塞&quot;，是以行為道，與常解異。○煬，從局本《睽》之《比》校改，宋元本、汲古本皆作易，非。兌亦形坎，故《易林》往往以兌為耳。</p><h3 id="觀之小過" tabindex="-1">觀之小過 <a class="header-anchor" href="#觀之小過" aria-label="Permalink to “觀之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>四亂不安，東西為患。退身止足，無出邦域。乃得完全，賴其生福。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震卦數四，兌毀，故曰四亂不安。震東兌西，互坎為患，艮為身，在下故曰退身。震足艮止，故曰止足。艮為邦域，震為生、為福，艮止巽伏，故無出邦域。</p><h3 id="觀之既濟" tabindex="-1">觀之既濟 <a class="header-anchor" href="#觀之既濟" aria-label="Permalink to “觀之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>班馬遠師，以息勞罷。役夫嘉喜，入戶見妻。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>坎為馬，重坎故曰班馬。坎為眾，故曰師。坎為勞疲，艮止，故曰以息勞罷。坎為役、為夫，震為喜，艮為戶，離為坎妻。既未濟用半象，易通例也。</p><h3 id="觀之未濟" tabindex="-1">觀之未濟 <a class="header-anchor" href="#觀之未濟" aria-label="Permalink to “觀之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>積德不怠，遇主逢時。載喜渭陽，身受榮光。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>坎為積，震主艮時，故曰遇主逢時。震車為載、為喜，坎水故曰渭。艮為身，離為光榮。多用半象。林意謂姜太公垂釣，遇文王於渭水，後受封也。○喜，依宋元本，汲古作善，為喜之訛。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
